S=/tmp/claude-0/-home-user-Claudinite/8a11c3c8-2cc3-54c3-b789-7eebf5e04130/scratchpad && BASE=$(cat $S/base.txt) && python3 - "$BASE" <<'PY'
import subprocess,sys,json
base=sys.argv[1]
packs=['basics','git-github','claudinite-lifecycle','claudinite-tasks','claudinite-growth','claudinite-canon-curation','claude-code-web-users-support']
def ids(ref,p):
    try:
        out=subprocess.run(['git','show',f'{ref}:packs/{p}/declared-checks.json'],capture_output=True,text=True,check=True).stdout
        return {e['id'] for e in json.loads(out)}
    except Exception: return set()
def mods(ref,p):
    out=subprocess.run(['git','ls-tree','-r','--name-only',ref,f'packs/{p}/'],capture_output=True,text=True).stdout.split()
    return {f for f in out if '/worldRules/' in f or '/workRules/' in f or '/actionRules/' in f}
for p in packs:
    nd=ids('HEAD',p)-ids(base,p); rd=ids(base,p)-ids('HEAD',p)
    nm=mods('HEAD',p)-mods(base,p); rm=mods(base,p)-mods('HEAD',p)
    if nd or rd or nm or rm:
        print(f'## {p}')
        if nd: print('  + declared:',sorted(nd))
        if rd: print('  - declared:',sorted(rd))
        if nm: print('  + modules:',sorted(nm))
        if rm: print('  - modules:',sorted(rm))
PY

