{
 "id": "bare-sleep-wait",
 "on_fail": "advise",
 "scope": "action",
 "failureMessage": "a padded sleep waits on nothing nameable; a guard that would not stand as the whole test is sleeping and calling it polling",
 "fix": "name the condition awaited \u2014 a run's status, a file's arrival, a deadline \u2014 and wait on that",
 "guardToolCalls": [
  {
   "tool": "Bash",
   "inputField": "command",
   "match": "/(^|[;&|]\\s*)sleep\\s+\\d+\\s*($|[;&|])/",
   "what": "a bare \"{match}\""
  },
  {
   "tool": "Bash",
   "inputField": "command",
   "match": "/\\bfor\\b[^;\\n]*;\\s*do\\s+sleep\\s+\\d+\\s*;\\s*done\\b/",
   "what": "a counted loop with nothing but a sleep in its body: \"{match}\""
  }
 ]
}
-----
{
 "id": "busy-wait-loop",
 "on_fail": "block",
 "since": "2026-09-11",
 "scope": "action",
 "failureMessage": "a loop body of `:` yields nothing, so the shell spins at full tilt and the session answers nobody until a person interrupts it",
 "guardToolCalls": [
  {
   "tool": "Bash",
   "inputField": "command",
   "match": "/(^|[;&|]\\s*|\\n\\s*)(until|while)\\b[^\\n]*;\\s*do\\s*(:|true)\\s*;\\s*done\\b/",
   "what": "a loop that spins without waiting: \"{match}\"",
   "fix": "sleep inside the loop body and bound the wait \u2014 or drop the loop: a background task's completion arrives as a notification"
  }
 ]
}
-----
{
 "id": "mount-path-in-the-canon-home",
 "on_fail": "block",
 "since": "2026-09-13",
 "scope": "action",
 "failureMessage": "the canon home carries no .claudinite/shared/ at all, so a module invoked through that path is Cannot find module and the sweep the session believed it ran never ran",
 "guardToolCalls": [
  {
   "tool": "Bash",
   "inputField": "command",
   "match": "/(^|[;&|(]\\s*|\\n\\s*)(?:[A-Za-z_][A-Za-z0-9_]*=[^\\s;&|]*\\s+)*(node|bash|sh)\\s+(--test\\s+)?\\.claudinite\\/shared\\//",
   "unlessMatches": "/(^|[;&|(]\\s*|\\n\\s*)cd\\s|PROJECT_DIR|--root|<<|\\|\\|\\s*(node|bash|sh)\\s/",
   "what": "an engine module run through the mount: \"{match}\"",
   "fix": "drop the prefix and run it from the repo root (node engine/checks/check_the_world.mjs); a member's checkout cloned into this session keeps the mount path, and needs the cd that says so"
  }
 ]
}
-----
{
 "id": "migration-record-paths-resolve",
 "on_fail": "block",
 "since": "2026-09-20",
 "failureMessage": "a canon path in a migration record fails open \u2014 an unreadable probe reads as \"not capable\", a missing template is skipped \u2014 so a move leaves the record silently inert",
 "scanIgnoringComments": true,
 "extractValueSets": [
  {
   "setName": "migrationCanonPaths",
   "fromLinesMatching": "/['\"`](?<value>(?:packs|engine)\\/[A-Za-z0-9_.-]+(?:\\/[A-Za-z0-9_.-]+)+)['\"`]/",
   "inFilesMatching": "/(^|\\/)migrations\\/[^/]+\\/migration\\.mjs$/",
   "whenSetEmpty": "assertNothing"
  }
 ],
 "checkSetValues": [
  {
   "setName": "migrationCanonPaths",
   "requirePathExists": "{value}",
   "what": "the record names {value}, which is not a path in this tree",
   "fix": "repoint it at the file's current path; where the target is gone for good, delete the probe or materialization naming it rather than leave one that can never fire"
  }
 ]
}
-----
{
 "id": "fixture-git-housekeeping",
 "on_fail": "block",
 "since": "2026-09-21",
 "failureMessage": "git's auto-gc detaches and keeps writing under .git after the command returns, so the fixture's removal races it: the suite passes locally and CI fails with ENOTEMPTY",
 "scanFiles": "/\\.test\\.mjs$/",
 "scanTracked": true,
 "scanIgnoringComments": true,
 "checkEachFile": [
  {
   "whenFileMatches": [
    "/(?:execFileSync|execSync|spawnSync|execFile|spawn)\\(\\s*'git'/",
    "/'(?:init|clone)'/"
   ],
   "require": "/gc\\.autoDetach/",
   "what": "builds a throwaway git repo with a spawn of its own, so git's housekeeping outlives the command that started it",
   "fix": "call the shared runner - `import { git } from '<relative>/engine-tests/helpers.mjs'`, then `git(root, 'init', '-q')` - or spawn with its GIT_CONFIG env, which holds gc.autoDetach and maintenance.auto off"
  }
 ]
}
-----
{
 "id": "pack-prose-paths-resolve",
 "on_fail": "block",
 "since": "2026-09-22",
 "failureMessage": "reference-integrity is work-scoped and sees only a path the same branch deletes, so a citation an earlier move stranded sends every later session into nothing",
 "scanIgnoringMarkdownFences": true,
 "extractValueSets": [
  {
   "setName": "citedCanonPaths",
   "fromLinesMatching": "/`(?<value>(?:packs|engine)\\/[A-Za-z0-9_.-]+(?:\\/[A-Za-z0-9_.-]+)*\\.(?:mjs|json|md|ya?ml|sh))`/",
   "inFilesMatching": "/(^|\\/)(?:packs|\\.claudinite\\/local\\/packs)\\/[^/]+\\/(?:RULES\\.md|skills\\/[^/]+\\/SKILL\\.md)$/",
   "whenSetEmpty": "assertNothing"
  }
 ],
 "checkSetValues": [
  {
   "setName": "citedCanonPaths",
   "requirePathExists": "{value}",
   "what": "the prose cites {value}, which is not a path in this tree",
   "fix": "repoint it at the file's current path, or drop the citation where the sentence reads without one"
  }
 ]
}
-----
{
 "id": "print-then-exit",
 "on_fail": "block",
 "since": "2026-09-22",
 "scope": "work",
 "failureMessage": "a pipe write is asynchronous and process.exit() drops what is still queued, so a caller capturing the output reads a truncated answer under a clean status",
 "excludeFileClasses": [
  "testFiles"
 ],
 "forbidAddedLinesMatching": [
  {
   "inFilesMatching": "/\\.(m|c)?js$/",
   "match": "/console\\.(log|error|warn)\\(.*process\\.exit\\(/",
   "unlessLineMatches": "/^\\s*(\\/\\/|\\/\\*|\\*)/",
   "what": "\"{match}\" prints and then exits hard on one line",
   "fix": "set process.exitCode and let the process end, adding a `return` where the exit was also ending the flow - or exit from the write's own callback, as hook-runner.mjs does"
  }
 ]
}
-----
{
 "id": "history-search-on-shallow-clone",
 "on_fail": "block",
 "since": "2026-09-23",
 "failureMessage": "a pickaxe or --reverse walk answers with the earliest commit the CHECKOUT reaches, so on a shallow clone it hands back the clone's own horizon as the repository's history",
 "scanFiles": "/\\.mjs$/",
 "scanIgnoringComments": true,
 "matchLines": [
  {
   "match": "/['\"`](?:log|rev-list)['\"`][^\\n]*(?:--reverse|['\"`\\s]-S)/",
   "unlessLineMatches": "/[^.]\\.\\.[^.]/",
   "unlessIndentedBlockBelowMatches": "/[^.]\\.\\.[^.]/",
   "unlessFileMatches": "/--is-shallow-repository|--unshallow/",
   "what": "asks history for its earliest hit: {match}",
   "fix": "probe `git rev-parse --is-shallow-repository` and say so rather than answering from the horizon, or `git fetch --unshallow` first; a walk bounded by a `<ref>..<ref>` range is out of scope"
  }
 ]
}
-----
{
 "id": "timed-phase-named-in-vocabulary",
 "on_fail": "block",
 "since": "2026-09-24",
 "failureMessage": "renderRunCost prints only the words RUN_PHASES names, so a phase timed under any other word is measured and then dropped, and the fold never sees what it cost",
 "scanIgnoringComments": true,
 "extractValueSets": [
  {
   "setName": "phasesTimed",
   "fromLinesMatching": "/\\b(?:phase\\(|timed\\([A-Za-z_$][\\w$]*,\\s*)'(?<value>[a-z][a-z-]*)'/",
   "inFilesMatching": "/^packs\\/claudinite-tasks\\/src\\/.+\\.mjs$/",
   "whenSetEmpty": {
    "what": "nothing under packs/claudinite-tasks/src/ opens a run phase under a literal word",
    "fix": "the timer's call shape moved, so repoint \"phasesTimed\" at how a phase is opened now, or retire this check if no run times itself any more"
   }
  },
  {
   "setName": "phasesNamed",
   "fromLinesMatching": "/^\\s*(?:scheduler|executor): Object\\.freeze\\(\\[(?<value>[^\\]]*)\\]\\)/",
   "inFilesMatching": "/(^|\\/)run-record\\.mjs$/",
   "splitValuesOn": "/[',\\s]+/",
   "whenSetEmpty": {
    "what": "RUN_PHASES names no phase word, so every timed phase would read as one this vocabulary does not have",
    "fix": "the declaration's shape moved, so repoint \"phasesNamed\" at where the per-workflow phase lists are spelled now"
   }
  }
 ],
 "checkSetPairs": [
  {
   "everyValueOf": "phasesTimed",
   "mustAlsoBeIn": "phasesNamed",
   "what": "the run times a phase under '{value}', which RUN_PHASES does not name",
   "fix": "add '{value}' to that workflow's list in RUN_PHASES, in the order the run executes it, or time the phase under a word the vocabulary already carries"
  }
 ]
}
-----
{
 "id": "generated-file-carries-no-banner",
 "on_fail": "block",
 "since": "2026-09-26",
 "failureMessage": "a generated file's banner is read by everyone and heeded by nobody: it repeats what the file's name or its directory already says, and every reader pays the line",
 "fix": "delete the banner where the generator writes it, not in the file it wrote",
 "scanFiles": "/.*/",
 "scanIgnoringMarkdownFences": true,
 "excludeFileClasses": [
  "testFiles"
 ],
 "matchLines": [
  {
   "match": "/^\\s*(<!--|#|\\/\\/|\\/\\*+)\\s*GENERATED\\b/",
   "what": "opens with a banner announcing the file generated: {match}"
  },
  {
   "match": "/^\\s*(<!--|\\/\\/|\\/\\*+)[^\\n]{0,90}generated\\b[^\\n]{0,90}(do not|don't|never)\\s+(hand-)?edit/i",
   "what": "carries a do-not-edit banner: {match}"
  }
 ]
}
-----

